public class Main {
    static int countUpper(String s) {
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= 'A' && c <= 'Z') count++;
        }
        return count;
    }
    public static void main(String[] args) {
        System.out.println(countUpper("AbZ"));
    }
}

