public class Main {
    static int[] prefixSums(int[] a) {
        int[] result = new int[a.length];
        int sum = 0;
        for (int i = 0; i < a.length; i++) {
            sum += a[i];
            result[i] = sum;
        }
        return result;
    }
    public static void main(String[] args) {
        System.out.println(java.util.Arrays.toString(prefixSums(new int[]{2, -1, 3})));
    }
}
